from collections import deque

def clone_graph(node):
    if not node:
        return None
    clones = {node: Node(node.val)}
    queue = deque([node])
    while queue:
        cur = queue.popleft()
        for nb in cur.neighbors:
            if nb not in clones:
                clones[nb] = Node(nb.val)  # first sighting: make the copy
                queue.append(nb)
            clones[cur].neighbors.append(clones[nb])
    return clones[node]

