def max_area_of_island(grid):
    m, n = len(grid), len(grid[0])
    best = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] != 1:
                continue
            grid[r][c] = 0
            stack, size = [(r, c)], 0
            while stack:
                i, j = stack.pop()
                size += 1
                for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                        grid[ni][nj] = 0
                        stack.append((ni, nj))
            best = max(best, size)
    return best

