    seen = set()
    for sr in range(m):
        for sc in range(n):
            if board[sr][sc] != 'O' or (sr, sc) in seen:
                continue
            region, stack, border = [], [(sr, sc)], False
            seen.add((sr, sc))
            while stack:               # collect one whole region
                r, c = stack.pop()
                region.append((r, c))
                border |= r in (0, m - 1) or c in (0, n - 1)
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n and board[nr][nc] == 'O' and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if not border:
                for r, c in region:    # enclosed: capture it
                    board[r][c] = 'X'
